using System.Text.RegularExpressions;
namespace UnscRelay.Core;
internal sealed record LocalErasureItem(string Relative,bool Link,long Bytes);
internal sealed record LocalErasureScope(string Relative,Guid Workspace,bool Backup);
internal sealed record LocalErasurePlan(LocalErasureNotice Notice,LocalErasureScope[] Scopes,LocalErasureItem[] Items,string[] Indexes,string[] Manifests,string[] Bindings,string[] Unattributed);
internal sealed class LocalErasurePlanner(string directory,LocalErasureJournal journal)
{
 internal static readonly string[] Files=["profiles.json","interface-language.json","keys.vault","keys.vault.before-windows-hello","keys.vault.before-passkeys","hostkeys.json","transfers.json","account-unlock.dpapi","account-hello.dpapi","sync-transaction.json"];
 internal static readonly string[] Folders=["ArchiveCopies","SyncConflicts","Recordings","Editor","NativeSessions","NativeHome","CertificateRequests","AssistantScratch","NativeBrowser","IdentityWebView","DragExports","LocalLaunch","WebView","Updates"];
 readonly string root=LocalDataFiles.Root(directory);
 string PathAt(string relative)=>relative.Length==0?root:LocalDataFiles.Child(root,relative);
 static string Join(string parent,string name)=>parent.Length==0?name:parent+"/"+name;
 string Leaf(string relative){var full=FolderSync.LocalChild(root,relative);FolderSync.CheckLocalParents(Path.GetDirectoryName(full)!);return full;}
 public LocalErasurePlan Create(string owner)
 {
  var notice=journal.Find(owner)??throw new InvalidDataException("La cancellazione locale non è stata registrata.");var ids=new HashSet<Guid>(notice.Workspaces);var scopes=new List<LocalErasureScope>();var items=new Dictionary<string,LocalErasureItem>(StringComparer.OrdinalIgnoreCase);var indexes=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var manifests=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var bindings=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var unattributed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  void AddItem(string relative,bool link,long bytes){if(items.Count>=100000)throw new IOException("La rimozione locale contiene troppi file. Nessun percorso esterno è stato incluso.");items[relative]=new(relative,link,bytes);}
  void Walk(string relative,int depth=0){if(depth>64)throw new IOException("Troppe cartelle nei dati locali.");var full=Leaf(relative);FileAttributes attributes;try{attributes=File.GetAttributes(full);}catch(FileNotFoundException){return;}catch(DirectoryNotFoundException){return;}if(attributes.HasFlag(FileAttributes.ReparsePoint)){AddItem(relative,true,0);return;}if(attributes.HasFlag(FileAttributes.Directory)){foreach(var child in new DirectoryInfo(full).EnumerateFileSystemInfos())Walk(Join(relative,child.Name),depth+1);}else AddItem(relative,false,new FileInfo(full).Length);}
  bool Belongs(string relative,Guid id,AccountWorkspaceIndex index){var path=PathAt(relative);var account=new AccountSyncStore(path).Load();if(account.Owner==notice.Owner&&account.Subject==notice.Subject)return true;if(account.Owner.Length==0&&(index.Accounts.Any(value=>value.Id==id&&value.Owner==notice.Owner)||notice.Workspaces.Contains(id))&&(Files.Any(name=>File.Exists(Path.Combine(path,name)))||Folders.Any(name=>Directory.Exists(Path.Combine(path,name)))))unattributed.Add(relative);return false;}
  IEnumerable<Guid> Discover(string baseRelative,AccountWorkspaceIndex index){var found=new HashSet<Guid>(ids);foreach(var account in index.Accounts.Where(value=>value.Owner==owner))found.Add(account.Id);var accounts=PathAt(Join(baseRelative,"Accounts"));if(Directory.Exists(accounts))foreach(var child in new DirectoryInfo(accounts).EnumerateDirectories()){if(!Guid.TryParseExact(child.Name,"N",out var id))continue;if(child.Attributes.HasFlag(FileAttributes.ReparsePoint))continue;var state=new AccountSyncStore(child.FullName).Load();if(state.Owner==owner&&state.Subject==notice.Subject)found.Add(id);}return found;}
  void Scope(string baseRelative,Guid id,bool backup,AccountWorkspaceIndex index){var relative=id==Guid.Empty?baseRelative:Join(baseRelative,"Accounts/"+id.ToString("N"));var full=PathAt(relative);if(!Directory.Exists(full))return;if(Belongs(relative,id,index)){ids.Add(id);scopes.Add(new(relative,id,backup));bindings.Add(Join(relative,"account-sync.dpapi"));foreach(var file in Files)Walk(Join(relative,file));foreach(var folder in Folders)Walk(Join(relative,folder));}var migrations=PathAt(Join(relative,"MigrationBackups"));if(Directory.Exists(migrations))foreach(var migration in new DirectoryInfo(migrations).EnumerateDirectories()){if(migration.Attributes.HasFlag(FileAttributes.ReparsePoint))throw new IOException("Una copia di migrazione è un collegamento.");if(!Regex.IsMatch(migration.Name,@"^\d{8}T\d{6}-[0-9a-f]{32}$",RegexOptions.CultureInvariant))continue;var child=Join(relative,"MigrationBackups/"+migration.Name);if(!Belongs(child,id,index))continue;scopes.Add(new(child,id,backup));bindings.Add(Join(child,"account-sync.dpapi"));foreach(var file in Files)Walk(Join(child,file));Walk(Join(child,"manifest.json"));foreach(var folder in Folders)Walk(Join(child,folder));}}
  var current=new AccountWorkspaces(root).Load();foreach(var id in Discover("",current))Scope("",id,false,current);indexes.Add("accounts.dpapi");
  var backupRoot=PathAt("UpdateBackups");if(Directory.Exists(backupRoot))foreach(var backup in new DirectoryInfo(backupRoot).EnumerateDirectories()){
   if(!Regex.IsMatch(backup.Name,@"^\d{8}-\d{6}-[0-9a-f]{32}$",RegexOptions.CultureInvariant))continue;if(backup.Attributes.HasFlag(FileAttributes.ReparsePoint))throw new IOException("Una copia di aggiornamento è un collegamento: nessun contenuto esterno verrà rimosso.");
   var relative="UpdateBackups/"+backup.Name;var index=new AccountWorkspaces(backup.FullName).Load();var before=scopes.Count;foreach(var id in Discover(relative,index))Scope(relative,id,true,index);if(scopes.Count>before){indexes.Add(relative+"/accounts.dpapi");manifests.Add(relative+"/manifest.json");}
  }
  return new(notice with{Workspaces=ids.Order().ToArray()},scopes.ToArray(),items.Values.OrderBy(item=>item.Relative,StringComparer.Ordinal).ToArray(),indexes.ToArray(),manifests.ToArray(),bindings.ToArray(),unattributed.ToArray());
 }
}
